lessonCode:
struct Animal {
    virtual string speak() const { return "..."; }
    virtual ~Animal() {}
};
struct Dog : Animal {
    string speak() const override { return "Woof"; }
};
Dog d; const Animal& a = d;
cout << a.speak();   // Woof

